const s = SceneManager._scene, m = $gameParty.members(), wh = 180, ww = 360, w2 = 408,
drawIt = (x, act) =>
  {x.drawActorSimpleStatus(act, 0, 0, ww); x.drawActorTp(act, wh - 2, w2 - 300, 176);
   x.drawActorFace(act, 0, 112, 144, 56)}; let n, w, a; if (!s._newWindow) s._newWindow = [];
for (n = 0; n < 4; n++) {a = m[n]; if (!a) {s._newWindow[n]?.destroy(); continue};
  w = s.getChildByName(`stats${n}`);
  if (!w) {w = s._newWindow[n] = new Window_Base(w2*n/2, Graphics.height - (wh/2), w2, wh);
    w.name = `stats${n}`; drawIt(w, a); w.scale.x = .5; w.scale.y = .5; s.addChild(w);
  } else {w.contents.clear(); drawIt(w, a)};
  if ($gameMessage.isBusy() && w.isOpen()) w.close();
  else if (!$gameMessage.isBusy() && w.isClosed()) w.open();
}
Cleaner looking code:
JavaScript:
const s = SceneManager._scene,
      m = $gameParty.members(),
     wh = 180, ww = 360, w2 = 408,
 drawIt = (x, act) => {
    x.drawActorSimpleStatus(act, 0, 0, ww);
    x.drawActorTp(act, wh - 2, w2 - 300, 176);
    x.drawActorFace(act, 0, 112, 144, 56)
};
let n, w, a;
if (!s._newWindow) s._newWindow = [];
for (n = 0; n < 4; n++) {
    a = m[n];
    if (!a) {
        s._newWindow[n]?.destroy();
        continue;
    }
    w = s.getChildByName(`stats${n}`);
    if (!w) {
        w = s._newWindow[n] = new Window_Base(w2 * n / 2, Graphics.height - (wh / 2), w2, wh);
        w.name = `stats${n}`;
        drawIt(w, a);
        w.scale.x = .5;
        w.scale.y = .5;
        s.addChild(w);
    } else {
        w.contents.clear();
        drawIt(w, a);
    }
    if ($gameMessage.isBusy() && w.isOpen()) w.close();
    else if (!$gameMessage.isBusy() && w.isClosed()) w.open();
}
Description:
Spoiler
Referenced from a later post:
I define all my constants at the beginning: Scene Manager's main scene, party members, window height/width and the content's width.
I create a constant function to simplify my use of existing functions so I don't have to write them again with the drawIt function which draws the actor's statuses, tp, and face. Other variables defined with let.
I then check to see if there is an array ._newWindow inside the Scene Manager, if not, create one (that way it doesn't keep overwriting it in the parallel).
I create a for loop that loops 0 to 3 where I:
- grab the child attached to the scene by name
- if there is nothing there, create a new window base and name it
- go through all party members, and if anything changes, destroy the window and create/update with a new one
- drawIt function called
- scale it so it actually fits since I am not able to resize text, etc. without going into the js and editing it (with a plugin, etc.) - I mean, yes, but I don't want to be overwriting code either at this point haha
- add it to the scene with .addChild()
- if all of that exists already, then just refresh the contents by clearing it and updating it with the drawIt function
- added game message functionality where the status windows close so the messages can be seen if needed (example: if you set your message to be at the top where the status windows are, the windows close)
- wait 4 frames (felt like this worked better for me for performance and efficiency)
